parameters.jsCode:
// Exnoria - prd.contact.nudge
// Branch on signal_id: PRD_FRC_01 (task abandonment) vs PRD_FRC_02 (low usage)
// Localized: en/es via APP_LOCALE

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, cause_code, interventions } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'there';
const email     = contact.properties?.email?.value     ?? '';
const phone     = contact.properties?.phone?.value     ?? '';

const es = $env.APP_LOCALE === 'es';

const cleanPhone = phone.replace(/[^\d]/g, '');

const greeting = es
  ? (firstname !== 'there' ? 'Hola ' + firstname + ',' : 'Hola,')
  : 'Hi ' + firstname + ',';

let message = '';
let action_type = '';

if (signal_id === 'PRD_FRC_01') {
  // Task abandonment — re-engagement tip
  message = es ? [
    greeting,
    '',
    'Dejaste algo pendiente — y creemos que estás muy cerca de un gran resultado.',
    '',
    'Aquí tienes un consejo rápido para continuar donde lo dejaste: [Enlace de Consejo]',
    '',
    '¿Necesitas ayuda? Solo responde a este mensaje.',
    '',
    '— Equipo de Producto Exnoria'
  ].join('\n') : [
    greeting,
    '',
    'You left something unfinished — and we think you\'re really close to a great result.',
    '',
    'Here\'s a quick tip to pick up where you left off: [Feature Tip Link]',
    '',
    'Need a hand? Just reply to this message.',
    '',
    '-- Exnoria Product Team'
  ].join('\n');
  action_type = 'reengagement_tip';
} else if (signal_id === 'PRD_FRC_02') {
  // Low usage of core features — enroll in adoption sequence
  message = es ? [
    greeting,
    '',
    'Hemos preparado una serie de consejos cortos para ayudarte a obtener más valor de tu cuenta.',
    '',
    'Recibirás 3 correos rápidos durante la próxima semana con consejos prácticos adaptados a tu caso de uso.',
    '',
    '— Equipo de Producto Exnoria'
  ].join('\n') : [
    greeting,
    '',
    'We\'ve put together a short series of tips to help you get more value from your account.',
    '',
    'You\'ll receive 3 quick emails over the next week with practical tips tailored to your use case.',
    '',
    '-- Exnoria Product Team'
  ].join('\n');
  action_type = 'adoption_sequence_enrollment';
} else {
  message = es
    ? greeting + ' tenemos algunos consejos para ayudarte a aprovechar más tu cuenta. ¡Responde si te interesa!'
    : 'Hi ' + firstname + ', we have some tips to help you get more from your account. Reply if interested!';
  action_type = 'generic_nudge';
}

const whatsapp_payload = cleanPhone ? {
  messaging_product: 'whatsapp',
  to: cleanPhone,
  type: 'text',
  text: { body: message }
} : null;

const nudgedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

return [{
  json: {
    contact_id,
    signal_id,
    cause_code,
    email,
    firstname,
    phone: cleanPhone,
    whatsapp_payload,
    action_type,
    sequence_id: signal_id === 'PRD_FRC_02' ? 'prd-adoption-series' : null,
    nudged_at: nudgedAt
  }
}];

